import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { doc, getDoc, collection, addDoc, Timestamp } from "firebase/firestore";
import { db } from "./firebase";
import { format } from "date-fns";
import GeneraVerbale from "./GeneraVerbale";
import Card from "react-bootstrap/Card";
import Button from "react-bootstrap/Button";
import Spinner from "react-bootstrap/Spinner";

const DettaglioIntervento = () => {
  const { interventoId } = useParams();
  const navigate = useNavigate();
  const [intervento, setIntervento] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchIntervento = async () => {
      try {
        const docRef = doc(db, "INTERVENTI", interventoId);
        const snapshot = await getDoc(docRef);
        if (snapshot.exists()) {
          setIntervento({ id: snapshot.id, ...snapshot.data() });
        } else {
          console.warn("Intervento non trovato");
        }
      } catch (error) {
        console.error("Errore nel recupero intervento:", error);
      } finally {
        setLoading(false);
      }
    };
    fetchIntervento();
  }, [interventoId]);

  const duplicaIntervento = async () => {
    if (!intervento) return;
    try {
      const nuovo = { ...intervento };
      delete nuovo.id;
      nuovo.data = Timestamp.now();
      nuovo.stato = "Effettuato";
      const docRef = await addDoc(collection(db, "INTERVENTI"), nuovo);
      alert("✅ Intervento duplicato con successo.");
      navigate(`/intervento/${docRef.id}`);
    } catch (error) {
      console.error("Errore nella duplicazione:", error);
      alert("❌ Errore nella duplicazione.");
    }
  };

  if (loading) {
    return (
      <div className="p-4 text-center">
        <Spinner animation="border" variant="primary" />
        <p className="mt-3 text-muted">Caricamento intervento...</p>
      </div>
    );
  }

  if (!intervento) {
    return <div className="p-4 text-danger">❌ Intervento non trovato.</div>;
  }

  const dataFormattata = intervento.data?.toDate?.()
    ? format(intervento.data.toDate(), "dd/MM/yyyy")
    : "—";

  return (
    <div className="p-4">
      <h3 className="mb-4">📄 Dettaglio Intervento</h3>
      <Card className="mb-3">
        <Card.Body>
          <p><strong>Data:</strong> {dataFormattata}</p>
          <p><strong>Tipo:</strong> {intervento.tipo || "—"}</p>
          <p><strong>Tecnico:</strong> {intervento.tecnico || "—"}</p>
          <p><strong>Firma:</strong> {intervento.firmaTecnico || "—"}</p>
          <p><strong>Cliente:</strong> {intervento.clienteNome || "—"}</p>
          <p><strong>Mezzo:</strong> {intervento.mezzoId || "—"}</p>
          <p><strong>Urgente:</strong> {intervento.urgente ? "✅ Sì" : "❌ No"}</p>
          <p><strong>Stato:</strong> {intervento.stato || "—"}</p>
          <p><strong>Note:</strong> {intervento.note || "Nessuna"}</p>
          {intervento.allegato && (
            <p>
              <strong>Allegato:</strong>{" "}
              <a href={intervento.allegato} target="_blank" rel="noopener noreferrer">
                📎 Visualizza
              </a>
            </p>
          )}
        </Card.Body>
      </Card>

      <div className="d-flex gap-3">
        <GeneraVerbale intervento={intervento} />
        <Button variant="warning" onClick={() => navigate(`/modifica/${intervento.id}`)}>
          ✏️ Modifica intervento
        </Button>
        <Button variant="secondary" onClick={duplicaIntervento}>
          📄 Duplica intervento
        </Button>
      </div>
    </div>
  );
};

export default DettaglioIntervento;