import React from "react";
import PropTypes from "prop-types";

/**
 * Visualizza il logo aziendale.
 * @param {Object} props
 * @param {number} props.altezza - Altezza in pixel
 * @param {number} [props.larghezza] - Larghezza opzionale
 * @param {string} props.className - Classi aggiuntive
 */
const LogoAziendale = ({ altezza = 40, larghezza, className = "" }) => {
  const larghezzaFinale = larghezza || Math.round(altezza * 2.5); // proporzione standard

  const handleLogoError = (e) => {
    e.target.onerror = null;
    e.target.src = "/fallback-logo.png";
  };

  return (
    <img
      src="/logo.png"
      alt="Logo aziendale EVI"
      height={altezza}
      width={larghezzaFinale}
      className={className}
      style={{
        objectFit: "contain",
        display: "block",
        height: `${altezza}px`,
        width: `${larghezzaFinale}px`,
        transition: "opacity 0.3s ease-in-out"
      }}
      aria-label="Logo aziendale"
      onError={handleLogoError}
    />
  );
};

LogoAziendale.propTypes = {
  altezza: PropTypes.number,
  larghezza: PropTypes.number,
  className: PropTypes.string
};

export default LogoAziendale;