import React, { useEffect, useState } from "react";
import { Calendar, momentLocalizer } from "react-big-calendar";
import moment from "moment";
import "react-big-calendar/lib/css/react-big-calendar.css";
import { collection, getDocs, updateDoc, doc } from "firebase/firestore";
import { db } from "./firebase";

const localizer = momentLocalizer(moment);

const CalendarioInterventi = () => {
  const [interventi, setInterventi] = useState([]);

  useEffect(() => {
    const fetchInterventi = async () => {
      const snapshot = await getDocs(collection(db, "INTERVENTI"));
      const dati = snapshot.docs.map(doc => {
        const data = doc.data();
        return {
          id: doc.id,
          title: data.titolo || "Intervento",
          start: data.data?.toDate?.() || new Date(),
          end: new Date((data.data?.toDate?.() || new Date()).getTime() + 3600000),
          resource: data
        };
      });
      setInterventi(dati);
    };
    fetchInterventi();
  }, []);

  const aggiornaData = async (event, start) => {
    try {
      const ref = doc(db, "INTERVENTI", event.id);
      await updateDoc(ref, { data: start });
    } catch (error) {
      console.error("Errore aggiornamento data:", error);
    }
  };

  return (
    <div className="p-4">
      <h3 className="mb-3">📅 Calendario Interventi</h3>
      <Calendar
        localizer={localizer}
        events={interventi}
        startAccessor="start"
        endAccessor="end"
        style={{ height: 600 }}
        onSelectEvent={(e) => console.log("Selezionato:", e)}
        onEventDrop={({ event, start }) => aggiornaData(event, start)}
        draggableAccessor={() => true}
      />
    </div>
  );
};

export default CalendarioInterventi;