import React, { useEffect, useState, useRef } from "react";
import { collection, getDocs } from "firebase/firestore";
import { db, auth, storage } from "firebase.js";
import { Line, Bar } from "react-chartjs-2";
import { format } from "date-fns";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  BarElement,
  Tooltip,
  Legend
} from "chart.js";
import Form from "react-bootstrap/Form";
import Button from "react-bootstrap/Button";
import Modal from "react-bootstrap/Modal";

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, BarElement, Tooltip, Legend);

const GraficoTrendMensile = () => {
  const [interventi, setInterventi] = useState([]);
  const [annoSelezionato, setAnnoSelezionato] = useState("");
  const [clienteFiltro, setClienteFiltro] = useState("");
  const [tipoFiltro, setTipoFiltro] = useState("");
  const [loading, setLoading] = useState(true);
  const [modalMese, setModalMese] = useState(null);
  const chartRef = useRef();

  useEffect(() => {
    const fetchInterventi = async () => {
      try {
        const snap = await getDocs(collection(db, "INTERVENTI"));
        const dati = snap.docs.map(doc => doc.data());
        setInterventi(dati);
      } catch (error) {
        console.error("Errore nel recupero interventi:", error);
      } finally {
        setLoading(false);
      }
    };
    fetchInterventi();
  }, []);

  const interventiFiltrati = interventi.filter(i => {
    const data = i.data?.toDate?.();
    if (!data || isNaN(data)) return false;
    const anno = format(data, "yyyy");
    const cliente = i.clienteNome || "";
    const tipo = i.tipo || "";
    return (
      (annoSelezionato ? anno === annoSelezionato : true) &&
      cliente.toLowerCase().includes(clienteFiltro.toLowerCase()) &&
      tipo.toLowerCase().includes(tipoFiltro.toLowerCase())
    );
  });

  const conteggioPerMese = interventiFiltrati.reduce((acc, i) => {
    const data = i.data?.toDate?.();
    if (!data || isNaN(data)) return acc;
    const mese = format(data, "yyyy-MM");
    acc[mese] = (acc[mese] || 0) + 1;
    return acc;
  }, {});

  const mesiOrdinati = Object.keys(conteggioPerMese).sort();
  const valori = mesiOrdinati.map(m => conteggioPerMese[m]);

  const cumulativo = valori.reduce((acc, val, i) => {
    acc.push((acc[i - 1] || 0) + val);
    return acc;
  }, []);

  const mediaMobile = valori.map((_, i, arr) => {
    const slice = arr.slice(Math.max(0, i - 2), i + 1);
    const media = slice.reduce((a, b) => a + b, 0) / slice.length;
    return Math.round(media * 100) / 100;
  });

  const dataLine = {
    labels: mesiOrdinati,
    datasets: [
      {
        label: "Interventi mensili",
        data: valori,
        borderColor: "#007bff",
        backgroundColor: "#007bff",
        tension: 0.3
      },
      {
        label: "Cumulativo",
        data: cumulativo,
        borderColor: "#28a745",
        backgroundColor: "#28a745",
        borderDash: [5, 5],
        tension: 0.3
      },
      {
        label: "Media mobile (3 mesi)",
        data: mediaMobile,
        borderColor: "#ffc107",
        backgroundColor: "#ffc107",
        tension: 0.3
      }
    ]
  };

  const clienti = [...new Set(interventiFiltrati.map(i => i.clienteNome || "—"))];
  const dataBar = {
    labels: clienti,
    datasets: [
      {
        label: "Interventi per cliente",
        data: clienti.map(c =>
          interventiFiltrati.filter(i => (i.clienteNome || "—") === c).length
        ),
        backgroundColor: "#17a2b8"
      }
    ]
  };

  const options = {
    responsive: true,
    plugins: {
      legend: { position: "top" },
      tooltip: { mode: "index", intersect: false }
    },
    scales: {
      x: {
        title: { display: true, text: "Mese" },
        ticks: { maxRotation: 45, minRotation: 45 }
      },
      y: {
        title: { display: true, text: "Numero interventi" },
        beginAtZero: true,
        precision: 0
      }
    },
    onClick: (_, elements) => {
      if (elements.length > 0) {
        const index = elements[0].index;
        setModalMese(mesiOrdinati[index]);
      }
    }
  };

  const anniDisponibili = [...new Set(
    interventi
      .map(i => i.data?.toDate?.())
      .filter(d => d instanceof Date && !isNaN(d))
      .map(d => format(d, "yyyy"))
  )].sort();

  const esportaPNG = () => {
    const chart = chartRef.current;
    if (chart) {
      const link = document.createElement("a");
      link.href = chart.toBase64Image();
      link.download = `trend_interventi_${annoSelezionato || "tutti"}.png`;
      link.click();
    }
  };

  const interventiDelMese = interventiFiltrati.filter(i =>
    format(i.data.toDate(), "yyyy-MM") === modalMese
  );

  return (
    <div className="p-4 bg-light rounded">
      <h4 className="mb-3">📈 Andamento Interventi Mensili</h4>

      <div className="d-flex gap-3 flex-wrap mb-4">
        <Form.Select
          value={annoSelezionato}
          onChange={(e) => setAnnoSelezionato(e.target.value)}
          style={{ maxWidth: "150px" }}
        >
          <option value="">Tutti gli anni</option>
          {anniDisponibili.map((a, i) => (
            <option key={i} value={a}>{a}</option>
          ))}
        </Form.Select>

        <Form.Control
          type="text"
          placeholder="🔍 Filtra per cliente..."
          value={clienteFiltro}
          onChange={(e) => setClienteFiltro(e.target.value)}
          style={{ maxWidth: "250px" }}
        />

        <Form.Control
          type="text"
          placeholder="🔍 Filtra per tipo..."
          value={tipoFiltro}
          onChange={(e) => setTipoFiltro(e.target.value)}
          style={{ maxWidth: "200px" }}
        />

        <Button variant="outline-primary" onClick={esportaPNG}>
          📤 Esporta PNG
        </Button>
      </div>

      {loading ? (
        <p className="text-muted">Caricamento dati...</p>
      ) : mesiOrdinati.length === 0 ? (
        <p className="text-muted">Nessun dato disponibile per il grafico.</p>
      ) : (
        <>
          <Line ref={chartRef} data={dataLine} options={options} />
          <div className="mt-5">
            <h5>📊 Interventi per Cliente</h5>
            <Bar data={dataBar} options={{ responsive: true, plugins: { legend: { display: false } } }} />
          </div>
        </>
      )}

      <Modal show={!!modalMese} onHide={() => setModalMese(null)} size="lg">
        <Modal.Header closeButton>
          <Modal.Title>📅 Dettaglio Interventi - {modalMese}</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          {interventiDelMese.length > 0 ? (
            <ul className="list-group">
              {interventiDelMese.map((i, idx) => (
                <li key={idx} className="list-group-item">
                  <strong>{format(i.data.toDate(), "dd/MM/yyyy")}</strong> — {i.tipo} — {i.clienteNome || "—"}
                </li>
              ))}
            </ul>
                    ) : (
            <p className="text-muted">
              Nessun intervento registrato per questo mese.
            </p>
          )}
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setModalMese(null)}>
            Chiudi
          </Button>
        </Modal.Footer>
      </Modal>
    </div>
  );
};

export default GraficoTrendMensile;