import React, { useEffect, useState } from "react";
import { MapContainer, TileLayer, Marker, Popup } from "react-leaflet";
import MarkerClusterGroup from "react-leaflet-cluster";
import { collection, getDocs, doc, updateDoc } from "firebase/firestore";
import { db } from "./firebase";
import L from "leaflet";
import "leaflet/dist/leaflet.css";

// Fix icone Leaflet
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: require("leaflet/dist/images/marker-icon-2x.png"),
  iconUrl: require("leaflet/dist/images/marker-icon.png"),
  shadowUrl: require("leaflet/dist/images/marker-shadow.png"),
});

// Funzione per geolocalizzare da indirizzo
const geolocalizzaIndirizzo = async (indirizzo) => {
  const url = `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(indirizzo)}`;
  const res = await fetch(url);
  const data = await res.json();
  if (data.length > 0) {
    return {
      lat: parseFloat(data[0].lat),
      lng: parseFloat(data[0].lon)
    };
  }
  return null;
};

const MappaClienti = () => {
  const [clienti, setClienti] = useState([]);

  useEffect(() => {
    const fetchClienti = async () => {
      const snap = await getDocs(collection(db, "CLIENTI"));
      const clientiRaw = snap.docs.map(doc => ({
        id: doc.id,
        ref: doc.ref,
        ...doc.data()
      }));

      const clientiGeolocalizzati = await Promise.all(
        clientiRaw.map(async cliente => {
          if (cliente.lat && cliente.lng) return cliente;

          if (!cliente.indirizzo) return null;

          const coords = await geolocalizzaIndirizzo(cliente.indirizzo);
          if (coords) {
            // Salva le coordinate su Firebase
            await updateDoc(cliente.ref, {
              lat: coords.lat,
              lng: coords.lng
            });
            return {
              ...cliente,
              lat: coords.lat,
              lng: coords.lng
            };
          }

          return null;
        })
      );

      const clientiValidi = clientiGeolocalizzati.filter(c => c && c.lat && c.lng);
      setClienti(clientiValidi);
    };

    fetchClienti();
  }, []);

  return (
    <div className="p-4 bg-light rounded">
      <h3 className="mb-4">🗺️ Mappa Clienti</h3>

      <MapContainer center={[43.5, 12.5]} zoom={6} style={{ height: "600px", width: "100%" }}>
        <TileLayer
          attribution='© OpenStreetMap'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />
        <MarkerClusterGroup>
          {clienti.map(c => (
            <Marker key={c.id} position={[c.lat, c.lng]}>
              <Popup>
                <strong>{c.ragioneSociale}</strong><br />
                {c.indirizzo}<br />
                {c.email || "—"}<br />
                {c.telefono || "—"}
              </Popup>
            </Marker>
          ))}
        </MarkerClusterGroup>
      </MapContainer>
    </div>
  );
};

export default MappaClienti;