import React, { useState, useEffect } from "react";
import { collection, getDocs } from "firebase/firestore";
import { db } from "./firebase";
import Form from "react-bootstrap/Form";
import Table from "react-bootstrap/Table";
import Button from "react-bootstrap/Button";
import { format } from "date-fns";
import { useNavigate, useLocation } from "react-router-dom";
import EsportaCSV from "./EsportaCSV";
import GeneraVerbale from "./GeneraVerbale";

const ReportInterventi = () => {
  const [interventi, setInterventi] = useState([]);
  const [filtrati, setFiltrati] = useState([]);
  const [tecnici, setTecnici] = useState([]);
  const [clienti, setClienti] = useState([]);
  const [filtro, setFiltro] = useState({
    tipo: "",
    tecnico: "",
    cliente: "",
    urgente: "",
    stato: "",
    scadenza: "",
    da: "",
    a: ""
  });

  const navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
    const fetchData = async () => {
      const interventiSnap = await getDocs(collection(db, "INTERVENTI"));
      const tecniciSnap = await getDocs(collection(db, "UTENTI"));
      const clientiSnap = await getDocs(collection(db, "CLIENTI"));

      const interventiData = interventiSnap.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      const tecniciData = tecniciSnap.docs
        .map(doc => doc.data())
        .filter(t => t.ruolo === "tecnico");
      const clientiData = clientiSnap.docs.map(doc => doc.data());

      setInterventi(interventiData);
      setTecnici(tecniciData);
      setClienti(clientiData);

      const params = new URLSearchParams(location.search);
      const urgenteParam = params.get("urgente");
      if (urgenteParam === "true") {
        setFiltro(prev => ({ ...prev, urgente: "true" }));
        const urgenti = interventiData.filter(i => i.urgente === true);
        setFiltrati(urgenti);
      } else {
        setFiltrati(interventiData);
      }
    };
    fetchData();
  }, [location]);

  const filtra = () => {
    let risultati = [...interventi];

    if (filtro.tipo) risultati = risultati.filter(i => i.tipo === filtro.tipo);
    if (filtro.tecnico) risultati = risultati.filter(i => i.tecnico === filtro.tecnico);
    if (filtro.cliente) risultati = risultati.filter(i => i.clienteNome === filtro.cliente);
    if (filtro.urgente) risultati = risultati.filter(i => i.urgente === (filtro.urgente === "true"));

    if (filtro.stato === "Effettuato") {
      risultati = risultati.filter(i => i.stato === "Effettuato");
    }
    if (filtro.stato === "Non effettuato") {
      risultati = risultati.filter(i => i.stato !== "Effettuato");
    }

    if (filtro.scadenza === "inScadenza") {
      const oggi = new Date();
      risultati = risultati.filter(i =>
        i.tipo === "Controllo" &&
        i.prossimaScadenza?.toDate &&
        i.prossimaScadenza.toDate() <= oggi
      );
    }

    if (filtro.da) {
      const daData = new Date(filtro.da);
      risultati = risultati.filter(i => i.data?.toDate && i.data.toDate() >= daData);
    }
    if (filtro.a) {
      const aData = new Date(filtro.a);
      risultati = risultati.filter(i => i.data?.toDate && i.data.toDate() <= aData);
    }

    setFiltrati(risultati);
  };

  const resetFiltri = () => {
    setFiltro({
      tipo: "",
      tecnico: "",
      cliente: "",
      urgente: "",
      stato: "",
      scadenza: "",
      da: "",
      a: ""
    });
    setFiltrati(interventi);
  };

  return (
    <div className="p-4 bg-light rounded">
      <h3 className="mb-4">📊 Report Interventi</h3>

      <Form className="mb-4">
        {/* Filtri */}
        {/* ... (tutti i Form.Group come già presenti) */}
        {/* Pulsanti */}
        <div className="d-flex gap-2 mt-3">
          <Button variant="primary" onClick={filtra}>🔍 Applica filtri</Button>
          <Button variant="outline-secondary" onClick={resetFiltri}>♻️ Reset</Button>
          <Button variant="outline-info" onClick={() => navigate("/calendario")}>📅 Calendario</Button>
          <EsportaCSV dati={filtrati} nomeFile="report_interventi.csv" />
        </div>
      </Form>

      <div className="mb-2 text-muted" style={{ fontSize: "0.9rem" }}>
        <span style={{ color: "#dc3545" }}>❗</span> = Non effettuato &nbsp;&nbsp;
        <span style={{ color: "#ffc107" }}>⏰</span> = Controllo in scadenza
      </div>

      <Table striped bordered hover responsive>
        <thead>
          <tr>
            <th>Data</th>
            <th>Tipo</th>
            <th>Tecnico</th>
            <th>Cliente</th>
            <th>Mezzo</th>
            <th>Urgente</th>
            <th>Stato</th>
            <th>PDF</th>
          </tr>
        </thead>
        <tbody>
          {filtrati.map((i) => {
            const isScadenza = i.tipo === "Controllo" && i.prossimaScadenza?.toDate && i.prossimaScadenza.toDate() <= new Date();
            const isNonEffettuato = i.stato !== "Effettuato";
            const rowClass = isNonEffettuato
              ? "riga-non-effettuato"
              : isScadenza
              ? "riga-scadenza"
              : "riga-effettuato";

            return (
              <tr key={i.id} className={rowClass}>
                <td>{i.data?.toDate ? format(i.data.toDate(), "dd/MM/yyyy") : "—"}</td>
                <td>{i.tipo}</td>
                <td>{i.tecnico}</td>
                <td>{i.clienteNome || "-"}</td>
                <td>{i.mezzoId || "-"}</td>
                <td>{i.urgente ? "✅" : "❌"}</td>
                <td>
                  {i.stato}
                  {isNonEffettuato && (
                    <span title="Intervento non ancora effettuato" style={{ marginLeft: "6px", color: "#dc3545" }}>
                      ❗
                    </span>
                  )}
                  {isScadenza && (
                    <span title="Controllo in scadenza" style={{ marginLeft: "6px", color: "#ffc107" }}>
                      ⏰
                    </span>
                  )}
                </td>
                <td><GeneraVerbale intervento={i} /></td>
              </tr>
            );
          })}
        </tbody>
      </Table>

      <div className="mt-4">
        <h5>🧠 Funzionalità avanzate</h5>
        <ul>
          <li>🔔 Notifiche automatiche per interventi in scadenza</li>
          <li>📅 Calendario interventi con visualizzazione mensile</li>
          <li>🧾 Generazione automatica di verbali PDF</li>
          <li>🔐 Accesso differenziato per ruoli (admin, tecnico, cliente)</li>
          <li>📤 Esportazione Excel / CSV dei report filtrati</li>
        </ul>
      </div>
    </div>
  );
};

export default ReportInterventi;